def next_smallest_palindrome(num):
    numstr = str(num)
    n = len(numstr)
    if all(ch == "9" for ch in numstr):
        return 10 ** n + 1
    # For even length
    if n % 2 == 0:
        left = numstr[: n // 2]
        pal = left + left[::-1]
        if int(pal) > num:
            return int(pal)
        left = str(int(left) + 1)
        pal = left + left[::-1]
        return int(pal)
    # For odd length
    else:
        left = numstr[: n // 2]
        mid = numstr[n // 2]
        pal = left + mid + left[::-1]
        if int(pal) > num:
            return int(pal)
        left = str(int(left) + 1)
        pal = left + mid + left[::-1]
        return int(pal)
```

