import math
def sumofFactors(n):
    if n % 2 != 0:
        return 0
    total = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            count = 0
            while n % i == 0:
                count += 1
                n //= i
            if count > 0:
                total *= (i ** (count + 1) - 1) // (i - 1)
        i += 1
    if n > 1:
        total *= (n + 1)
    return total
```

