def max_product(arr):
    n = len(arr)
    dp = [1] * n  # dp[i] will hold the max product for the subsequence ending at i

    for i in range(n):
        dp[i] = arr[i]  # At least the number itself is a valid subsequence
        for j in range(i):
            if arr[j] < arr[i]:  # Only consider increasing subsequences
                dp[i] = max(dp[i], dp[j] * arr[i])
    return max(dp)
```

